SELECT c.CariHareketID, Format(c.Tarih,"dd.mm.yyyy") AS Tarih, c.MusteriID, m.AdSoyad AS Müşteri, p.PartiKodu AS Parti, c.HareketTuru AS Hareket, c.Aciklama AS Açıklama, Format(Nz(c.Borc,0),"#,##0.00") AS Borç, Format(Nz(c.Alacak,0),"#,##0.00") AS Alacak, Format(Nz(m.AcilisBakiyesi,0)+Nz((SELECT Sum(Nz(x.Borc,0)-Nz(x.Alacak,0)) FROM tbl_CariHareket AS x WHERE x.MusteriID=c.MusteriID AND x.IptalMi=False AND (x.Tarih<c.Tarih OR (x.Tarih=c.Tarih AND x.CariHareketID<=c.CariHareketID))),0),"#,##0.00") AS Kalan, Switch(Nz(c.KaynakTipi,"")="PARTI","Üretim",Nz(c.KaynakTipi,"")="TESLIM","Teslim",Nz(c.KaynakTipi,"")="KASA","Kasa/Banka",Nz(c.KaynakTipi,"")="ALIMSATIM","Alım/Satım",True,"Manuel") AS Kaynak, c.Tarih AS TarihHam
FROM (tbl_CariHareket AS c INNER JOIN tbl_Musteri AS m ON c.MusteriID=m.MusteriID) LEFT JOIN tbl_Parti AS p ON c.PartiNo=p.PartiNo
WHERE c.IptalMi=False;